    private void gatherRunePouchContents(RaidPartyPlayerSync sync) {
        try {
            final int[] RUNE_POUCH_AMOUNT_VARBITS = {
                    Varbits.RUNE_POUCH_AMOUNT1, Varbits.RUNE_POUCH_AMOUNT2, Varbits.RUNE_POUCH_AMOUNT3,
                    Varbits.RUNE_POUCH_AMOUNT4
            };
            final int[] RUNE_POUCH_RUNE_VARBITS = {
                    Varbits.RUNE_POUCH_RUNE1, Varbits.RUNE_POUCH_RUNE2, Varbits.RUNE_POUCH_RUNE3,
                    Varbits.RUNE_POUCH_RUNE4
            };

            List<Integer> ids = new ArrayList<>();
            List<Integer> qtys = new ArrayList<>();

            EnumComposition runepouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
            for (int i = 0; i < RUNE_POUCH_AMOUNT_VARBITS.length; i++) {
                int amount = client.getVarbitValue(RUNE_POUCH_AMOUNT_VARBITS[i]);
                if (amount <= 0)
                    continue;
                int runeId = client.getVarbitValue(RUNE_POUCH_RUNE_VARBITS[i]);
                if (runeId == 0)
                    continue;
                int itemId = runepouchEnum.getIntValue(runeId);
                ids.add(itemId);
                qtys.add(amount);
            }

            sync.setRunePouchIds(ids.stream().mapToInt(Integer::intValue).toArray());
            sync.setRunePouchQtys(qtys.stream().mapToInt(Integer::intValue).toArray());
        } catch (Exception e) {
            sync.setRunePouchIds(new int[0]);
            sync.setRunePouchQtys(new int[0]);
        }
    }

    private int[] gatherSkillLevels() {
        Skill[] skills = Skill.values();
        int[] levels = new int[skills.length * 2];
        for (int i = 0; i < skills.length; i++) {
            try {
                levels[i * 2] = client.getBoostedSkillLevel(skills[i]);
                levels[i * 2 + 1] = client.getRealSkillLevel(skills[i]);
            } catch (Exception ignored) {
            }
        }
        return levels;
    }

    private int[] gatherSkillXps() {
        Skill[] skills = Skill.values();
        int[] xps = new int[skills.length];
        for (int i = 0; i < skills.length; i++) {
            try {
                xps[i] = client.getSkillExperience(skills[i]);
            } catch (Exception ignored) {
            }
        }
        return xps;
    }

    // --- AUTO-LEAVE ON IDLE ---
    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGIN_SCREEN) {
            lastLogout = Instant.now();
        } else if (event.getGameState() == GameState.LOGGED_IN) {
            // Force a full party sync once we enter the game so our newly populated arrays broadcast
            forceFullSync = true;
            lastSentUsername = null;
            lastSentInvHash = -1;
            lastSentEqpHash = -1;
            lastSentSkillsHash = -1;
            lastSentRunePouchHash = -1;
            lastSentXpsHash = -1;
            needsPartySync = true;

            // Ensure native party service is updated upon login
            if (partyService != null && partyService.getLocalMember() != null) {
                String name = getLocalPlayerName();
                if (name != null && !name.isEmpty()) {
                    partyService.getLocalMember().setDisplayName(name);
                }
            }
        }
    }

    @Subscribe
    public void onChatMessage(net.runelite.api.events.ChatMessage event) {
        if (!config.announceMegarares() || partyService == null || !partyService.isInParty()) {
            return;
        }

        if (event.getType() != net.runelite.api.ChatMessageType.GAMEMESSAGE &&
            event.getType() != net.runelite.api.ChatMessageType.SPAM &&
            event.getType() != net.runelite.api.ChatMessageType.BROADCAST) {
            return;
        }

        // Prevent player-spoofed chat messages
        if (event.getName() != null && !event.getName().isEmpty()) {
            return;
        }

        String rawMessage = net.runelite.client.util.Text.removeTags(event.getMessage());
        String message = rawMessage.toLowerCase();

        // Check if it's a drop message
        if (!message.contains("special loot:") && !message.contains("found some loot:") && !message.contains("received a drop:") && !message.contains("found some special loot:") && !message.contains("found something special:") && !message.contains("valuable drop:")) {
            return;
        }

        java.util.Map<String, Integer> megarares = new HashMap<>();
        megarares.put("twisted bow", 20997);
        megarares.put("kodai insignia", 21043);
        megarares.put("elder maul", 21003);
        megarares.put("dragon hunter crossbow", 21012);
        megarares.put("dinh's bulwark", 21015);
        megarares.put("ancestral hat", 21018);
        megarares.put("ancestral robe top", 21021);
        megarares.put("ancestral robe bottom", 21024);
        megarares.put("dragon claws", 13652);
        megarares.put("twisted buckler", 21000);
        megarares.put("scythe of vitur", 22486); // Uncharged
        megarares.put("ghrazi rapier", 22324);
        megarares.put("sanguinesti staff", 22323); // Uncharged
        megarares.put("justiciar faceguard", 22326);
        megarares.put("justiciar chestguard", 22327);
        megarares.put("justiciar legguards", 22328);
        megarares.put("avernic defender hilt", 22477);
        megarares.put("tumeken's shadow", 27277); // Uncharged
        megarares.put("elidinis' ward", 25985);
        megarares.put("osmumten's fang", 26219);
        megarares.put("lightbearer", 25975);
        megarares.put("masori mask", 27226);
        megarares.put("masori body", 27229);
        megarares.put("masori chaps", 27232);

        String matchedItem = null;
        int matchedId = -1;
        for (Map.Entry<String, Integer> entry : megarares.entrySet()) {
            if (message.contains(entry.getKey())) {
                matchedItem = entry.getKey();
                matchedId = entry.getValue();
                break;
            }
        }

        boolean isHighValueCoinMessage = false;
        long parsedCoins = 0;
        java.util.regex.Matcher m = java.util.regex.Pattern.compile("\\(([\\d,]+) coins\\)").matcher(rawMessage);
        if (m.find()) {
            try {
                parsedCoins = Long.parseLong(m.group(1).replace(",", ""));
                if (parsedCoins >= 10_000_000) {
                    isHighValueCoinMessage = true;
                }
            } catch (Exception e) {}
        }

        if (matchedItem != null || isHighValueCoinMessage) {
            String playerName = "Someone";
            if (message.contains(" - ")) { // CoX style: "Special loot: Patrolman - Twisted bow"
                String[] parts = rawMessage.split(" - ");
                if (parts.length >= 2) {
                    playerName = parts[0].replace("Special loot:", "").trim();
                }
            } else if (message.contains("received a drop:")) {
                playerName = rawMessage.split("received a drop:")[0].trim();
            } else if (message.contains("found some special loot:")) {
                playerName = rawMessage.split("found some special loot:")[0].trim();
            } else if (message.contains("found something special:")) {
                playerName = rawMessage.split("found something special:")[0].trim();
            } else if (message.contains("found some loot:")) {
                playerName = rawMessage.split("found some loot:")[0].trim();
            } else if (message.contains("valuable drop:")) {
                playerName = client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : "You";
            }

            // Format name properly
            if (playerName.length() > 0) {
                playerName = playerName.substring(0, 1).toUpperCase() + playerName.substring(1);
            }

            String finalItemName = "";
            long price = 0;

            if (matchedItem != null) {
                // Title case the item name
                for (String word : matchedItem.split(" ")) {
                    if (!finalItemName.isEmpty()) finalItemName += " ";
                    finalItemName += word.substring(0, 1).toUpperCase() + word.substring(1);
                }
                price = itemManager.getItemPrice(matchedId);
            } else {
                // Extract the item name from the message before the '('
                java.util.regex.Matcher nameMatcher = java.util.regex.Pattern.compile(":\\s*(?:\\d+\\s*x\\s*)?([^(]+)\\s*\\(").matcher(rawMessage);
                if (nameMatcher.find()) {
                    finalItemName = nameMatcher.group(1).trim();
                } else {
                    finalItemName = "Valuable Item";
                }
                price = parsedCoins;
            }

            String priceStr = price > 0 ? java.text.NumberFormat.getInstance().format(price) : "Unknown";

            String date = java.time.LocalDate.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
            String dropMessage = playerName + " Received: <col=ef20ff>" + finalItemName + "</col> [<col=00ff00>" + priceStr + "</col> gp] [" + date + "]";
            postPartyChat(dropMessage);

            if (config.takeDropScreenshot()) {
                clientThread.invokeLater(() -> {
                    takeEvidenceScreenshot("Drops");
                });
            }
        }
    }

    @Schedule(period = 10, unit = ChronoUnit.SECONDS)
    public void checkIdle() {
        if (client.getGameState() != GameState.LOGIN_SCREEN)
            return;
        if (lastLogout != null && lastLogout.isBefore(Instant.now().minus(30, ChronoUnit.MINUTES))
                && partyService.isInParty()) {
            log.info("Leaving party due to 30 minute idle timeout");
            partyService.changeParty(null);
            SwingUtilities.invokeLater(() -> panel.updateConnectionState(false, ""));
        }
    }

    public RaidPartyConfig getConfig() {
        return config;
    }

    // --- Ready Check ---
    public int getLocalReadyState() {
        return localReadyState;
    }

    public void setReadyState(int state) {
        localReadyState = state;
        cachedLocalSync.setReadyState(state);

        if (state > 0) {
            if (config.chatReadyToggle() && System.currentTimeMillis() - lastChatBroadcastTime > 1500) {
                String name = getLocalPlayerName();
                if (name == null) name = "Unknown";
                String statusText = state == 1 ? "is now <col=00ff00>Ready</col>"
                        : "is now <col=ff0000>Not Ready</col>";
                postPartyChat(name + " " + statusText);
                lastChatBroadcastTime = System.currentTimeMillis();
            }
        }

        if (partyService.isInParty()) {
            needsPartySync = true;
        }
    }

    public void resetReadyState() {
        boolean changed = false;
        if (localReadyState != 0) {
            localReadyState = 0;
            if (cachedLocalSync != null) {
                cachedLocalSync.setReadyState(0);
            }
            needsPartySync = true;
            partySyncTimer = 0; // Force immediate broadcast to party
            changed = true;
        }
        for (RaidPartyPlayerSync s : partyData.values()) {
            if (s != null && s.getReadyState() != 0) {
                s.setReadyState(0);
                changed = true;
            }
        }
        if (changed && panel != null) {
            javax.swing.SwingUtilities.invokeLater(() -> panel.repaint());
        }
    }

    // --- Loot Rule ---
    public void setLootRule(LootRule rule) {
        if (isLootLocked()) {
            return; // Block changing loot rule while actively inside a raid
        }
        localLootRule = rule;
        cachedLocalSync.setLootRule(rule);

        // Broadcast to party chat locally
        if (rule != LootRule.UNSPECIFIED) {
            if (config.chatLootToggle() && System.currentTimeMillis() - lastChatBroadcastTime > 1500) {
                String name = getLocalPlayerName();
                if (name == null) name = "Unknown";
                String color = rule == LootRule.FFA ? "af00af" : "00bfff";
                postPartyChat(name + " Loot Confirmed: <col=" + color + ">" + rule + "</col>");
                lastChatBroadcastTime = System.currentTimeMillis();
            }
        }

        if (partyService.isInParty()) {
            needsPartySync = true;
        }
    }

    public boolean isPartyMemberWithLocalPlayer(RaidPartyPlayerSync syncData) {
        if (syncData == null || client.getLocalPlayer() == null) return false;
        if (partyService != null && partyService.getLocalMember() != null) {
            if (syncData.getMemberId() == partyService.getLocalMember().getMemberId()) {
                return true;
            }
        }
        // 1. Must be on exact same world
        if (syncData.getWorld() == 0 || syncData.getWorld() != client.getWorld()) {
            return false;
        }
        // 2. If we are in an instanced region (Raid rooms, boss rooms, instanced lobbies),
        // check if their character entity is loaded inside our exact instance!
        if (isPlayerInRaid() || (client.isInInstancedRegion() && client.getLocalPlayer().getLocalLocation() != null)) {
            String targetUsername = syncData.getUsername();
            if (targetUsername != null && !targetUsername.isEmpty()) {
                String cleanTarget = net.runelite.client.util.Text.removeTags(targetUsername).toLowerCase();
                if (client.getPlayers() != null) {
                    for (net.runelite.api.Player p : client.getPlayers()) {
                        if (p != null && p.getName() != null) {
                            String cleanPlayer = net.runelite.client.util.Text.removeTags(p.getName()).toLowerCase();
                            if (cleanPlayer.equals(cleanTarget)) {
                                return true;
                            }
                        }
                    }
                }
                return false; // On same world, but NOT inside our instanced raid/room!
            }
        }

        // 3. Fallback (not inside raid instance, no active party board registered): return true if on our exact same world
        return true;
    }

    public boolean isPlayerInRaid() {
        if (client.getLocalPlayer() == null) return false;

        // 1. CoX Varbit & Region check (Consider in-raid immediately upon entering lobby to lock loot)
        try {
            if (client.getVarbitValue(Varbits.IN_RAID) == 1 && client.isInInstancedRegion() && client.getVarbitValue(6386) != 0) {
                return true;
            }
        } catch (Exception ignored) {}

        // 2. ToB Varbit check (2=Inside/Spectator, 3=Dead Spectating)
        try {
            int tobState = client.getVarbitValue(Varbits.THEATRE_OF_BLOOD);
            if ((tobState == 2 || tobState == 3) && client.isInInstancedRegion()) return true;
        } catch (Exception ignored) {}

        // 3. (Removed ToA Varbit check because TOA_RAID_LEVEL persists outside the raid)

        // 4. Region ID checks (Supports both Instanced and Static regions)
        int instancedRegion = -1;
        if (client.isInInstancedRegion() && client.getLocalPlayer().getLocalLocation() != null) {
            net.runelite.api.coords.WorldPoint wp = net.runelite.api.coords.WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation());
            if (wp != null) {
                instancedRegion = wp.getRegionID();
            }
        }
        int worldRegion = client.getLocalPlayer().getWorldLocation().getRegionID();

        int[] regionsToCheck = {instancedRegion, worldRegion};
        for (int region : regionsToCheck) {
            if (region == -1) continue;

            // ToA Rooms (Lobby, Nexus, Kephri, Zebak, Akkha, Baba, Wardens, Loot)
            if (region == 14674 || region == 14676 || region == 14160 || region == 14162 || region == 14163 || 
                region == 14164 || region == 14686 || region == 14687 || region == 14688 || 
                region == 15184 || region == 15186 || region == 15187 || region == 15188 || 
                region == 15696 || region == 15698 || region == 15699 || region == 15700) {
                return true;
            }
            // ToB Rooms (Maiden, Bloat, Nylocas, Sotetseg, Xarpus, Verzik, Loot)
            if (region == 12611 || region == 12612 || region == 12613 || region == 13122 || region == 13123 || region == 13125 || region == 12867) {
                return true;
            }
            // CoX Rooms (Olm room specifically if varbits delayed, excluding gearing lobby 13138)
            if (region == 12889) {
                return true;
            }
        }

        return false;
    }

    private boolean cachedInRaid = false;

    public boolean isLootLocked() {
        return cachedInRaid;
    }

    // --- Evidence ---
    private void triggerRaidStartEvidence() {
        if (partyService == null || !partyService.isInParty()) return;

        String date = java.time.LocalDate.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
        StringBuilder sb = new StringBuilder();
        sb.append("<col=ffffff>Raid Started [</col><col=909090>").append(date).append("</col><col=ffffff>]! Rules:</col> ");
        boolean first = true;
        for (net.runelite.client.party.PartyMember member : partyService.getMembers()) {
            if (member == null) continue;
            RaidPartyPlayerSync sync = partyData.get(member.getMemberId());
            if (config.filterRaidScreenshots() && sync != null && !isPartyMemberWithLocalPlayer(sync)) {
                continue;
            }
            if (!first) sb.append("<col=ffffff>, </col>");

            sb.append("<col=55aaff>").append(member.getDisplayName()).append("</col> ");

            if (sync != null && sync.getLootRule() != null && sync.getLootRule() != LootRule.UNSPECIFIED) {
                String color = sync.getLootRule() == LootRule.FFA ? "af00af" : "00bfff";
                sb.append("<col=").append(color).append(">(").append(sync.getLootRule().name()).append(")</col>");
            } else {
                sb.append("<col=ff5555>(Unspecified)</col>");
            }
            first = false;
        }

        if (first) {
            sb.append("<col=ff5555>None</col>");
        }

        if (config.printRaidStartRules()) {
            postPartyChat(sb.toString());
        }

        if (config.takeRaidStartScreenshot()) {
            // Delay screenshot by 6 game ticks (~3.6 seconds) to ensure black loading screen fades
            evidenceScreenshotTicks = 6;
        }
    }

    private void takeEvidenceScreenshot(String subDir) {
        java.util.function.Consumer<Image> imageCallback = (img) -> {
            Graphics2D graphics = (Graphics2D) img.getGraphics();

            String date = java.time.LocalDate.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd"));
            String time = java.time.LocalTime.now().format(DateTimeFormatter.ofPattern("HH:mm:ss"));
            String playerName = client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : "Unknown";
            String watermark = "RaidParty Verified - " + date + " " + time + " - " + playerName;

            // --- 1% Stealth Chatbox Seal ---
            net.runelite.api.widgets.Widget chatbox = client.getWidget(net.runelite.api.widgets.ComponentID.CHATBOX_FRAME);
            if (chatbox != null && !chatbox.isHidden()) {
                java.awt.Rectangle bounds = chatbox.getBounds();
                graphics.setClip(bounds);

                Color stealthText = new Color(255, 255, 255, 3); // 1% white
                Color stealthShadow = new Color(0, 0, 0, 3);     // 1% black

                // Smaller font for tighter stacking inside the chatbox
                graphics.setFont(new Font("Arial", Font.BOLD, 18));
                FontMetrics sm = graphics.getFontMetrics();
                int sWidth = sm.stringWidth(watermark) + 10;
                int sHeight = sm.getHeight() + 5;

                for (int y = bounds.y; y < bounds.y + bounds.height + sHeight; y += sHeight) {
                    for (int x = bounds.x; x < bounds.x + bounds.width; x += sWidth) {
                        graphics.setColor(stealthShadow);
                        graphics.drawString(watermark, x + 1, y + 1);
                        graphics.setColor(stealthText);
                        graphics.drawString(watermark, x, y);
                    }
                }
                graphics.setClip(null);
            }
            graphics.dispose();

            BufferedImage bufferedImage = (BufferedImage) img;
            imageCapture.takeScreenshot(bufferedImage, "RaidParty", subDir, false, ImageUploadStyle.NEITHER);
        };

        drawManager.requestNextFrameListener(imageCallback);
    }


}

package com.github.kalsupes.raidparty;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.party.PartyMember;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import java.awt.*;

public class RaidPartyOverlay extends Overlay {
    private final Client client;
    private final RaidPartyPlugin plugin;

    private final RaidPartyConfig config;

    @Inject
    public RaidPartyOverlay(Client client, RaidPartyPlugin plugin, RaidPartyConfig config) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        Font originalFont = graphics.getFont();
        Stroke originalStroke = graphics.getStroke();
        long now = System.currentTimeMillis();

        // Remove expired pings atomically
        plugin.getActivePings().removeIf(p -> now > p.getExpiryTime());

        for (RaidPartyPlugin.BossPing ping : plugin.getActivePings()) {
            if (ping.getPoint().getPlane() != client.getPlane())
                continue;

            long remaining = ping.getExpiryTime() - now;
            float lifespanPct = Math.max(0, remaining / 2000f); // 0 to 1 based on 2s total life

            Color baseColor;
            java.awt.Shape shapeToDraw = null;
            String floatingText = "";
            net.runelite.api.Point floatingPoint = null;

            if (ping.getTargetType() == 1) { // NPC Target
                net.runelite.api.NPC npc = null;
                for (net.runelite.api.NPC n : client.getNpcs()) {
                    if (n != null && n.getIndex() == ping.getTargetIndex()) {
                        npc = n;
                        break;
                    }
                }

                if (npc != null) {
                    baseColor = config.entityPingColor();
                    shapeToDraw = npc.getConvexHull();
                    floatingText = Text.removeTags(npc.getName());
                    if (floatingText != null) {
                        floatingPoint = npc.getLogicalHeight() > 0
                                ? npc.getCanvasTextLocation(graphics, floatingText, npc.getLogicalHeight() + 40)
                                : net.runelite.api.Perspective.localToCanvas(client, npc.getLocalLocation(),
                                        client.getPlane(), 200);
                    }
                } else {
                    continue; // Skip rendering if NPC died or despawned
                }
            } else if (ping.getTargetType() == 2) { // GameObject Target
                LocalPoint lp = LocalPoint.fromWorld(client, ping.getPoint());
                if (lp == null)
                    continue;

                net.runelite.api.Tile tile = client.getScene().getTiles()[client.getPlane()][lp.getSceneX()][lp
                        .getSceneY()];
                net.runelite.api.TileObject targetObj = null;
                if (tile != null) {
                    if (tile.getWallObject() != null && tile.getWallObject().getId() == ping.getTargetIndex()) {
                        targetObj = tile.getWallObject();
                    } else if (tile.getDecorativeObject() != null
                            && tile.getDecorativeObject().getId() == ping.getTargetIndex()) {
                        targetObj = tile.getDecorativeObject();
                    } else if (tile.getGroundObject() != null
                            && tile.getGroundObject().getId() == ping.getTargetIndex()) {
                        targetObj = tile.getGroundObject();
                    } else {
                        net.runelite.api.GameObject[] gameObjects = tile.getGameObjects();
                        if (gameObjects != null) {
                            for (net.runelite.api.GameObject obj : gameObjects) {
                                if (obj != null && obj.getId() == ping.getTargetIndex()) {
                                    targetObj = obj;
                                    break;
                                }
                            }
                        }
                    }
                }

                if (targetObj != null) {
                    baseColor = config.objectPingColor();
                    if (targetObj instanceof net.runelite.api.GameObject) {
                        shapeToDraw = ((net.runelite.api.GameObject) targetObj).getConvexHull();
                    }
                    if (shapeToDraw == null)
                        shapeToDraw = targetObj.getClickbox();
                    if (shapeToDraw == null)
                        shapeToDraw = Perspective.getCanvasTilePoly(client, lp);

                    net.runelite.api.ObjectComposition def = client.getObjectDefinition(targetObj.getId());
                    if (def != null) {
                        if (def.getImpostorIds() != null) {
                            def = def.getImpostor();
                        }
                        if (def != null)
                            floatingText = Text.removeTags(def.getName());
                    }

                    int hoverHeight = 150 + (int) (Math.sin(System.currentTimeMillis() / 200.0) * 20); // Bobbing up and
                                                                                                       // down
                    floatingPoint = Perspective.localToCanvas(client, lp, client.getPlane(), hoverHeight);
                } else {
                    continue;
                }
            } else if (ping.getTargetType() == 3) { // GroundItem Target
                LocalPoint lp = LocalPoint.fromWorld(client, ping.getPoint());
                if (lp == null)
                    continue;

                net.runelite.api.Tile tile = client.getScene().getTiles()[client.getPlane()][lp.getSceneX()][lp
                        .getSceneY()];
                net.runelite.api.TileItem targetItem = null;
                if (tile != null) {
                    java.util.List<net.runelite.api.TileItem> groundItems = tile.getGroundItems();
                    if (groundItems != null) {
                        for (net.runelite.api.TileItem item : groundItems) {
                            if (item.getId() == ping.getTargetIndex()) {
                                targetItem = item;
                                break;
                            }
                        }
                    }
                }

                if (targetItem != null) {
                    baseColor = config.itemPingColor();
                    shapeToDraw = Perspective.getCanvasTilePoly(client, lp);

                    net.runelite.api.ItemComposition def = client.getItemDefinition(targetItem.getId());
                    if (def != null)
                        floatingText = Text.removeTags(def.getName());

                    int hoverHeight = 150 + (int) (Math.sin(System.currentTimeMillis() / 200.0) * 20); // Bobbing up and
                                                                                                       // down
                    floatingPoint = Perspective.localToCanvas(client, lp, client.getPlane(), hoverHeight);
                } else {
                    continue;
                }
            } else { // Tile Target
                LocalPoint lp = LocalPoint.fromWorld(client, ping.getPoint());
                if (lp == null)
                    continue;

                shapeToDraw = Perspective.getCanvasTilePoly(client, lp);

                if (ping.getPingType() == 2) {
                    baseColor = config.colorblindMode().adjustColor(config.dangerPingColor(), 2);
                    floatingText = "X";
                } else if (ping.getPingType() == 1) {
                    baseColor = config.colorblindMode().adjustColor(config.cautionPingColor(), 1);
                    floatingText = "!";
                } else if (ping.getPingType() == 3) {
                    baseColor = config.colorblindMode().adjustColor(config.resourcePingColor(), 3);
                    floatingText = "+";
                } else {
                    baseColor = config.colorblindMode().adjustColor(config.safePingColor(), 0);
                    floatingText = "v";
                }

                int hoverHeight = 150 + (int) (Math.sin(System.currentTimeMillis() / 200.0) * 20); // Bobbing up and
                                                                                                   // down
                floatingPoint = Perspective.localToCanvas(client, lp, client.getPlane(), hoverHeight);
            }

            if (shapeToDraw != null) {
                graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

                // Draw filled polygon (either tile or hull)
                graphics.setColor(new Color(baseColor.getRed(), baseColor.getGreen(), baseColor.getBlue(),
                        (int) (50 * lifespanPct)));
                graphics.fill(shapeToDraw);

                // Core solid bright line
                graphics.setColor(new Color(baseColor.getRed(), baseColor.getGreen(), baseColor.getBlue(),
                        (int) (255 * lifespanPct)));
                graphics.setStroke(new BasicStroke(2f));
                graphics.draw(shapeToDraw);
            }

            // Hovering 3D Icon / Name Renderer
            if (config.drawPingIcons() && floatingPoint != null && lifespanPct > 0.1f && floatingText != null
                    && !floatingText.isEmpty()) {
                graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
                graphics.setFont(new Font("Arial", Font.BOLD, ping.getTargetType() == 1 ? 16 : 36));

                FontMetrics metrics = graphics.getFontMetrics();
                int x = floatingPoint.getX() - metrics.stringWidth(floatingText) / 2;
                int y = floatingPoint.getY() + metrics.getAscent() / 4;

                // Draw black drop shadow for 3D effect
                graphics.setColor(Color.BLACK);
                graphics.drawString(floatingText, x + (ping.getTargetType() == 1 ? 1 : 2),
                        y + (ping.getTargetType() == 1 ? 1 : 2));

                // Draw actual text
                graphics.setColor(new Color(baseColor.getRed(), baseColor.getGreen(), baseColor.getBlue(),
                        (int) (255 * lifespanPct)));
                graphics.drawString(floatingText, x, y);
            }
        }

        graphics.setFont(originalFont);
        graphics.setStroke(originalStroke);

        // --- Low HP Player Glow ---
        java.util.List<net.runelite.api.Player> players = client.getPlayers();
        for (int pIdx = 0; pIdx < players.size(); pIdx++) {
            net.runelite.api.Player p = players.get(pIdx);
            if (p == null || p.getName() == null)
                continue;

            String cleanPName = net.runelite.client.util.Text.standardize(p.getName());

            boolean isLocal = (p == client.getLocalPlayer());
            boolean inParty = plugin.getPartyService() != null && plugin.getPartyService().isInParty();

            // Only render other players if we are in a party
            if (!isLocal && !inParty)
                continue;

            RaidPartyPlayerSync syncData = null;
            if (isLocal) {
                syncData = plugin.getLocalPlayerSync();
            } else {
                for (RaidPartyPlayerSync s : plugin.getPartyData().values()) {
                    if (s != null && s.getUsername() != null) {
                        String sName = net.runelite.client.util.Text.standardize(s.getUsername());
                        if (sName.equals(cleanPName)) {
                            syncData = s;
                            break;
                        }
                    }
                }

                // Fallback to partyService names
                if (syncData == null) {
                    for (net.runelite.client.party.PartyMember pm : plugin.getPartyService().getMembers()) {
                        if (pm.getDisplayName() != null) {
                            String pmName = net.runelite.client.util.Text.standardize(pm.getDisplayName());
                            if (pmName.equals(cleanPName)) {
                                syncData = plugin.getPartyData().get(pm.getMemberId());
                                break;
                            }
                        }
                    }
                }
            }

            if (!isLocal && config.drawOverheadNames()) {
                boolean isFriendOrClan = p.isFriend() || p.isClanMember() || p.isFriendsChatMember();
                if (!isFriendOrClan || !config.suppressOverheadForFriends()) {
                    boolean isPartyMember = (syncData != null);

                    if (!isPartyMember) {
                        for (net.runelite.client.party.PartyMember pm : plugin.getPartyService().getMembers()) {
                            if (pm.getDisplayName() != null) {
                                String pmName = net.runelite.client.util.Text.standardize(pm.getDisplayName());
                                if (pmName.equals(cleanPName)) {
                                    isPartyMember = true;
                                    break;
                                }
                            }
                        }
                    }

                    if (isPartyMember) {
                        String cleanName = Text.sanitize(p.getName());
                        int zOffset = p.getLogicalHeight() + 40;
                        net.runelite.api.Point textLoc = p.getCanvasTextLocation(graphics, cleanName, zOffset);
                        if (textLoc != null) {
                            Color nameColor = Color.WHITE; // Default White
                            if (syncData != null && syncData.getLootRule() != null) {
                                if (syncData.getLootRule() == LootRule.FFA) {
                                    nameColor = new Color(175, 0, 175); // FFA Purple
                                } else if (syncData.getLootRule() == LootRule.SPLIT) {
                                    nameColor = new Color(0, 191, 255); // Split Cyan
                                }
                            }
                            OverlayUtil.renderTextLocation(graphics, textLoc, cleanName, nameColor);
                        }
                    }
                }
            }

            if (syncData != null && syncData.getMaxHp() > 0) {
                float hpPct = (float) syncData.getHp() / syncData.getMaxHp();
                Color glowColor = null;

                if (hpPct <= config.criticalHpThreshold() / 100f && config.enableCriticalHpGlow()) {
                    glowColor = config.colorblindMode().adjustColor(config.criticalHpColor(), 2);
                } else if (hpPct <= config.lowHpThreshold() / 100f && config.enableLowHpGlow()) {
                    glowColor = config.colorblindMode().adjustColor(config.lowHpColor(), 4);
                }

                if (glowColor != null) {
                    java.awt.Shape hull = p.getConvexHull();
                    if (hull != null) {
                        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

                        // High-speed pulsing multiplier
                        float pulse = 0.5f + (float) (Math.sin(System.currentTimeMillis() / 100.0) * 0.5f);

                        // Emulate a blurred glow by drawing multiple fading thick strokes
                        for (int i = 0; i < 4; i++) {
                            float glowAlpha = 1f - (i / 4f);
                            graphics.setColor(new Color(glowColor.getRed(), glowColor.getGreen(), glowColor.getBlue(),
                                    (int) (120 * glowAlpha * pulse)));
                            graphics.setStroke(new BasicStroke(2f + (i * 3f)));
                            graphics.draw(hull);
                        }

                        // Core solid bright line
                        graphics.setColor(new Color(glowColor.getRed(), glowColor.getGreen(), glowColor.getBlue(),
                                (int) (255 * pulse)));
                        graphics.setStroke(new BasicStroke(1.5f));
                        graphics.draw(hull);
                    }
                }
            }
        }

        return null;
    }
}

package com.github.kalsupes.raidparty;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.OverlayUtil;

@Singleton
public class RaidPartyMinimapOverlay extends Overlay {
    private final Client client;
    private final PartyService partyService;
    private final RaidPartyPlugin plugin;
    private final RaidPartyConfig config;

    @Inject
    public RaidPartyMinimapOverlay(Client client, PartyService partyService, RaidPartyPlugin plugin, RaidPartyConfig config) {
        this.client = client;
        this.partyService = partyService;
        this.plugin = plugin;
        this.config = config;
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(OverlayPriority.HIGH);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!config.drawMinimap() || partyService == null || !partyService.isInParty()) {
            return null;
        }

        java.util.List<net.runelite.api.Player> players = client.getPlayers();
        for (int pIdx = 0; pIdx < players.size(); pIdx++) {
            Player player = players.get(pIdx);
            if (player == null || player == client.getLocalPlayer() || player.getName() == null) {
                continue;
            }

            String cleanPName = net.runelite.client.util.Text.standardize(player.getName());
            boolean isPartyMember = false;
            RaidPartyPlayerSync sync = null;

            // Check partyData map first (most authoritative for RaidParty sync)
            for (RaidPartyPlayerSync s : plugin.getPartyData().values()) {
                if (s.getUsername() != null) {
                    String sName = net.runelite.client.util.Text.standardize(s.getUsername());
                    if (sName.equals(cleanPName)) {
                        isPartyMember = true;
                        sync = s;
                        break;
                    }
                }
            }

            // Fallback to core partyService
            if (!isPartyMember && partyService != null) {
                for (net.runelite.client.party.PartyMember pm : partyService.getMembers()) {
                    if (pm.getDisplayName() != null) {
                        String pmName = net.runelite.client.util.Text.standardize(pm.getDisplayName());
                        if (pmName.equals(cleanPName)) {
                            isPartyMember = true;
                            sync = plugin.getPartyData().get(pm.getMemberId());
                            break;
                        }
                    }
                }
            }

            if (isPartyMember) {
                Point minimapLocation = player.getMinimapLocation();
                if (minimapLocation != null) {
                    Color color = Color.WHITE; // Default white
                    if (sync != null && sync.getLootRule() != null) {
                        if (sync.getLootRule() == LootRule.FFA) {
                            color = new Color(175, 0, 175); // FFA purple
                        } else if (sync.getLootRule() == LootRule.SPLIT) {
                            color = new Color(0, 191, 255); // Split cyan
                        }
                    }

                    if (config.drawMinimapDots()) {
                        OverlayUtil.renderMinimapLocation(graphics, minimapLocation, color);
                    }

                    if (config.drawMinimapNames()) {
                        OverlayUtil.renderTextLocation(graphics, minimapLocation, cleanPName, color);
                    }
                }
            }
        }
        return null;
    }
}

package com.github.kalsupes.raidparty;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.util.ColorUtil;

@Singleton
public class RaidPartyStatusOverlay extends Overlay
{
    private static final Color COLOR_HEALTH_MAX = Color.green;
    private static final Color COLOR_HEALTH_MIN = Color.red;
    private static final Color COLOR_PRAYER = new Color(50, 200, 200);
    private static final Color COLOR_STAMINA = new Color(160, 124, 72);
    private static final Color COLOR_SPEC = new Color(225, 225, 0);
    private static final Font OVERLAY_FONT = FontManager.getRunescapeBoldFont().deriveFont(16f);

    private final Client client;
    private final SpriteManager spriteManager;
    private final RaidPartyConfig config;
    private final PartyService partyService;
    private final RaidPartyPlugin plugin;

    @Inject
    public RaidPartyStatusOverlay(
        Client client, SpriteManager spriteManager,
        RaidPartyConfig config, PartyService partyService, RaidPartyPlugin plugin
    )
    {
        this.client = client;
        this.spriteManager = spriteManager;
        this.partyService = partyService;
        this.plugin = plugin;
        this.config = config;

        setLayer(OverlayLayer.UNDER_WIDGETS);
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(PRIORITY_HIGH);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!partyService.isInParty())
        {
            return null;
        }

        for (Player player : client.getPlayers())
        {
            if (!config.statusOverlayRenderSelf() && player == client.getLocalPlayer())
            {
                continue;
            }

            RaidPartyPlayerSync partyData = findPartySync(player);
            if (partyData == null)
            {
                continue;
            }

            int renderIx = 0;
            graphics.setFont(OVERLAY_FONT);
            if (config.statusOverlayHealth())
            {
                double healthRatio = partyData.getMaxHp() > 0 ? Math.min(1.0, (double) partyData.getHp() / partyData.getMaxHp()) : 1.0;
                Color healthColor = ColorUtil.colorLerp(COLOR_HEALTH_MIN, COLOR_HEALTH_MAX, healthRatio);
                renderPlayerOverlay(graphics, player, String.valueOf(partyData.getHp()), healthColor, renderIx++);
            }
            if (config.statusOverlayPrayer())
            {
                renderPlayerOverlay(graphics, player, String.valueOf(partyData.getPrayer()), COLOR_PRAYER, renderIx++);
            }
            if (config.statusOverlayStamina())
            {
                renderPlayerOverlay(graphics, player, String.valueOf(partyData.getRun()), COLOR_STAMINA, renderIx++);
            }
            if (config.statusOverlaySpec())
            {
                renderPlayerOverlay(graphics, player, String.valueOf(partyData.getSpec()), COLOR_SPEC, renderIx);
            }
            if (config.statusOverlayVeng() && partyData.isVengeanceActive())
            {
                BufferedImage vengIcon = spriteManager.getSprite(SpriteID.LunarMagicOn.VENGEANCE_OTHER, 0);
                if (vengIcon != null)
                {
                    renderPlayerOverlay(graphics, player, vengIcon);
                }
            }
        }

        return null;
    }

    private RaidPartyPlayerSync findPartySync(Player p)
    {
        if (p == null || p.getName() == null)
        {
            return null;
        }

        String cleanPName = p.getName().replace('\u00A0', ' ');
        for (RaidPartyPlayerSync sync : plugin.getPartyData().values()) {
            if (sync != null && sync.getUsername() != null && sync.getUsername().replace('\u00A0', ' ').equalsIgnoreCase(cleanPName)) {
                return sync;
            }
        }

        if (partyService != null) {
            for (PartyMember pm : partyService.getMembers()) {
                if (pm != null && pm.getDisplayName() != null && pm.getDisplayName().replace('\u00A0', ' ').equalsIgnoreCase(cleanPName)) {
                    return plugin.getPartyData().get(pm.getMemberId());
                }
            }
        }
        return null;
    }

    private void renderPlayerOverlay(Graphics2D graphics, Player player, String text, Color color, int renderIx)
    {
        Point point = Perspective.localToCanvas(client, player.getLocalLocation(), client.getPlane(), player.getLogicalHeight());

        if (point != null)
        {
            FontMetrics fm = graphics.getFontMetrics();
            int size = fm.getHeight();
            int zOffset = size * renderIx;

            OverlayUtil.renderTextLocation(
                graphics,
                new Point(point.getX() + size + 5, point.getY() + zOffset),
                text,
                color
            );
        }
    }

    private void renderPlayerOverlay(Graphics2D graphics, Player player, BufferedImage image)
    {
        Point textLocation = player.getCanvasImageLocation(image, player.getLogicalHeight() / 2);
        if (textLocation != null)
        {
            OverlayUtil.renderImageLocation(graphics, textLocation, image);
        }
    }
}

package com.github.kalsupes.raidparty;

public enum ColorblindMode {
    NONE("None"),
    DEUTERANOPE("Deuteranope"),
    PROTANOPE("Protanope"),
    TRITANOPE("Tritanope");

    private final String name;

    ColorblindMode(String name) {
        this.name = name;
    }

    public java.awt.Color adjustColor(java.awt.Color original, int pingType) {
        if (this == NONE) return original;

        // pingType: 0=Safe(Green), 1=Caution(Yellow), 2=Danger/CriticalHP(Red), 3=Resource(Blue), 4=LowHP(Yellow)
        if (this == DEUTERANOPE || this == PROTANOPE) {
            if (pingType == 0) return java.awt.Color.decode("#00A2FF"); // Sky Blue
            if (pingType == 2) return java.awt.Color.decode("#D55E00"); // Vermilion
            if (pingType == 1 || pingType == 4) return java.awt.Color.decode("#FFC20A"); // Bright Gold
            if (pingType == 3) return java.awt.Color.decode("#CC00FF"); // Magenta
        } else if (this == TRITANOPE) {
            if (pingType == 1 || pingType == 4) return java.awt.Color.decode("#FFC0CB"); // Pink
            if (pingType == 3) return java.awt.Color.decode("#00FFFF"); // Cyan
        }

        return original;
    }

    @Override
    public String toString() {
        return name;
    }
}

