    public void updateConnectionState(boolean connected, String passphrase) {
        SwingUtilities.invokeLater(() -> {
            centerContainer.removeAll();

            if (connected) {
                currentPassphrase = passphrase;
                // Check config for default mask state
                // Default to masked; toggled via panel button
                passphraseMasked = true;
                applyPassphraseMask();
                northCardLayout.show(northActionsContainer, "CONNECTED");
                centerContainer.add(rosterContainer, BorderLayout.NORTH);
            } else {
                currentPassphrase = "";
                northCardLayout.show(northActionsContainer, "DISCONNECTED");
                centerContainer.add(emptyStateLabel, BorderLayout.NORTH);
                rosterContainer.removeAll();
                memberCards.clear();
            }

            northActionsContainer.revalidate();
            northActionsContainer.repaint();
            centerContainer.revalidate();
            centerContainer.repaint();
        });
    }

    private void applyPassphraseMask() {
        if (passphraseMasked) {
            passphraseInput.setText("•".repeat(Math.max(8, currentPassphrase.length())));
            togglePassphraseBtn.setText("👁");
            togglePassphraseBtn.setToolTipText("Show passphrase");
        } else {
            passphraseInput.setText(currentPassphrase);
            togglePassphraseBtn.setText("🙈");
            togglePassphraseBtn.setToolTipText("Hide passphrase");
        }
    }

    public void addMember(String username, boolean isLocal) {
        RaidPartyPlayerSync dummySync = new RaidPartyPlayerSync();
        dummySync.setUsername(username);
        addMember(dummySync, isLocal);
    }

    public void addMember(RaidPartyPlayerSync sync, boolean isLocal) {
        SwingUtilities.invokeLater(() -> {
            String username = sync.getUsername();
            if (username == null) return;

            String rawName = username.trim();
            if (rawName.isEmpty() || rawName.equalsIgnoreCase("<unknown>")) {
                return;
            }

            String sanitized = username.toLowerCase().replace("\u00A0", " ");
            if (memberCards.containsKey(sanitized)) {
                memberCards.get(sanitized).updateSyncData(sync);
                return;
            }

            RaidPartyPlayerCard card = new RaidPartyPlayerCard(plugin, username, isLocal, sync);
            card.setAlignmentX(Component.CENTER_ALIGNMENT);
            memberCards.put(sanitized, card);

            rosterContainer.add(card);
            rosterContainer.add(Box.createRigidArea(new Dimension(0, 4)));
            rosterContainer.revalidate();
            rosterContainer.repaint();
        });
    }

    public void refreshRosterContainer() {
        rosterContainer.removeAll();
        for (RaidPartyPlayerCard card : memberCards.values()) {
            rosterContainer.add(card);
            rosterContainer.add(Box.createRigidArea(new Dimension(0, 4)));
        }
        rosterContainer.revalidate();
        rosterContainer.repaint();
    }

    public void removeMember(String username) {
        if (username == null) return;
        SwingUtilities.invokeLater(() -> {
            String sanitized = username.toLowerCase().replace("\u00A0", " ");
            if (memberCards.remove(sanitized) != null) {
                refreshRosterContainer();
            }
        });
    }

    public void removeMemberById(long memberId) {
        SwingUtilities.invokeLater(() -> {
            boolean changed = memberCards.values().removeIf(c -> c.getSyncData() != null && c.getSyncData().getMemberId() == memberId);
            if (changed) {
                memberCards.entrySet().removeIf(e -> !memberCards.containsValue(e.getValue()));
                refreshRosterContainer();
            }
        });
    }

    public void removeAllMembers() {
        SwingUtilities.invokeLater(() -> {
            memberCards.clear();
            refreshRosterContainer();
        });
    }

    public void reconcileMembers(java.util.Set<String> activeUsernames) {
        if (activeUsernames == null) return;
        SwingUtilities.invokeLater(() -> {
            boolean changed = false;
            java.util.Iterator<String> it = memberCards.keySet().iterator();
            while (it.hasNext()) {
                String u = it.next();
                if (!activeUsernames.contains(u)) {
                    it.remove();
                    changed = true;
                }
            }
            if (changed) {
                refreshRosterContainer();
            }
        });
    }

    public void onPlayerSync(RaidPartyPlayerSync sync) {
        if (sync == null || sync.getUsername() == null)
            return;

        String rawName = sync.getUsername().trim();
        if (rawName.isEmpty() || rawName.equalsIgnoreCase("<unknown>")) {
            return;
        }

        SwingUtilities.invokeLater(() -> {
            String sanitized = sync.getUsername().toLowerCase().replace("\u00A0", " ");
            RaidPartyPlayerCard card = memberCards.get(sanitized);
            if (card != null) {
                card.updateSyncData(sync);
            } else {
                addMember(sync, false);
            }
        });
    }

    private JButton createLootBtn(String text, LootRule rule, Color selectedColor, Color pressedColor,
            JPanel parentRow) {
        JButton btn = new JButton(text) {
            @Override
            protected void paintComponent(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                boolean locked = plugin.isLootLocked();
                boolean selected = plugin.getLocalLootRule() == rule;
                if (selected) {
                    g2.setColor(locked ? selectedColor.darker() : (getModel().isPressed() ? pressedColor : selectedColor));
                } else {
                    g2.setColor(locked ? new Color(30, 30, 30) : (getModel().isPressed() ? new Color(40, 40, 40) : new Color(60, 60, 60)));
                }
                g2.fillRoundRect(0, 0, getWidth(), getHeight(), 14, 14);
                g2.dispose();
                super.paintComponent(g);
            }
        };
        btn.setFont(FontManager.getRunescapeSmallFont());
        btn.setForeground(Color.WHITE);
        btn.setFocusPainted(false);
        btn.setContentAreaFilled(false);
        btn.setBorderPainted(false);
        btn.setOpaque(false);
        btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        btn.addMouseListener(new java.awt.event.MouseAdapter() {
            @Override
            public void mouseEntered(java.awt.event.MouseEvent e) {
                if (plugin.isLootLocked()) {
                    btn.setCursor(Cursor.getPredefinedCursor(Cursor.DEFAULT_CURSOR));
                } else {
                    btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
                }
            }
        });

        btn.addActionListener(e -> {
            if (plugin.isLootLocked()) {
                JOptionPane.showMessageDialog(this,
                    "Loot rule selection is locked while inside an active raid instance.\nTeleport out or finish the raid to change your selection.",
                    "Loot Rule Locked", JOptionPane.WARNING_MESSAGE);
                return;
            }
            if (rule == LootRule.FFA) {
                int res = JOptionPane.showOptionDialog(this,
                    "FFA = Free For All\n\nThis means any loot obtained by you is not susceptible to be split between your teammates.",
                    "Confirm Loot Rule", JOptionPane.YES_NO_OPTION, JOptionPane.QUESTION_MESSAGE, null, new String[]{"Confirm", "Decline"}, "Confirm");
                if (res != JOptionPane.YES_OPTION) return;
            } else if (rule == LootRule.SPLIT) {
                int res = JOptionPane.showOptionDialog(this,
                    "SPLIT\n\nThis means that any loot obtained by you is to be split with your teammates.",
                    "Confirm Loot Rule", JOptionPane.YES_NO_OPTION, JOptionPane.QUESTION_MESSAGE, null, new String[]{"Confirm", "Decline"}, "Confirm");
                if (res != JOptionPane.YES_OPTION) return;
            }
            plugin.setLootRule(rule);
            parentRow.repaint();
        });
        return btn;
    }

    private JButton createIconButton(String path, String tooltip, String url) {
        JButton btn = new JButton();
        try {
            BufferedImage img = ImageUtil.loadImageResource(RaidPartyPlugin.class, path);
            if (img != null) {
                img = ImageUtil.resizeImage(img, 24, 24);
                btn.setIcon(new ImageIcon(img));
            }
        } catch (Exception e) {}

        btn.setPreferredSize(new Dimension(32, 32));
        btn.setToolTipText(tooltip);
        btn.setFocusPainted(false);
        btn.setBackground(new Color(35, 35, 35));
        btn.setBorder(BorderFactory.createLineBorder(new Color(60, 60, 60)));
        btn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        btn.addActionListener(e -> LinkBrowser.browse(url));
        return btn;
    }

    public static class FlatButton extends JButton {
        private final Color baseColor;
        private final Color hoverColor;
        private boolean isHovered = false;

        public FlatButton(String text, Color base, Color hover) {
            super(text);
            this.baseColor = base;
            this.hoverColor = hover;

            setFont(FontManager.getRunescapeBoldFont());
            setForeground(Color.WHITE);
            setFocusPainted(false);
            setCursor(new Cursor(Cursor.HAND_CURSOR));
            setBorder(new EmptyBorder(8, 12, 8, 12));
            setContentAreaFilled(false);

            addMouseListener(new java.awt.event.MouseAdapter() {
                public void mouseEntered(java.awt.event.MouseEvent e) {
                    isHovered = true;
                    repaint();
                }

                public void mouseExited(java.awt.event.MouseEvent e) {
                    isHovered = false;
                    repaint();
                }
            });
        }

        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            int w = getWidth();
            int h = getHeight();

            Color bg = isHovered ? new Color(40, 45, 50, 220) : new Color(25, 27, 30, 180);
            g2.setColor(bg);
            g2.fillRoundRect(0, 0, w, h, 8, 8);

            Color borderColor = baseColor;
            if (isHovered)
                borderColor = borderColor.brighter();

            g2.setColor(borderColor);
            g2.setStroke(new BasicStroke(1.5f));
            g2.drawRoundRect(1, 1, w - 3, h - 3, 6, 6);

            g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            FontMetrics fm = g2.getFontMetrics();
            int stringWidth = fm.stringWidth(getText());
            int stringX = (w - stringWidth) / 2;
            int stringY = (h - fm.getHeight()) / 2 + fm.getAscent();

            g2.setColor(Color.BLACK);
            g2.drawString(getText(), stringX + 1, stringY + 1);

            g2.setColor(getForeground());
            g2.drawString(getText(), stringX, stringY);

            g2.dispose();
        }
    }
}

