@Value
public class PartyStatChange implements PartyProcess
{
	int s; // Skill ordinal
	int l; // Level
	int b; // Boosted Level

	@Override
	public void process(PartyPlayer p)
	{
		final Skill skill = Skill.values()[s];
		p.getStats().getBaseLevels().put(skill, l);
		p.getStats().getBoostedLevels().put(skill, b);
	}
}

